  $menu_def[3]=$is_platform_owner?array('admin'):array_values(array_filter($menu_access->resolve_roles($menu_def[3]),function($r)use($menu_access,$menu_def,$role,$menu_role_key){return $menu_access->allowed($r===$role?$menu_role_key:$r,$menu_def[0]);}));
  $menu_groups[$menu_group_name][1][]=$menu_def;
 }
}
unset($menu_group_name,$menu_group_def,$menu_def);
function admin_menu_active($path,$uri){
 if($path==='admin')return $uri==='admin';
 // Halaman form memakai bentuk tunggal: admin/post/agenda, admin/page/1, admin/quick_link/2.
 foreach(array('admin/officials'=>'admin/official','admin/pages'=>'admin/page','admin/quick_links'=>'admin/quick_link') as $list=>$form)if($path===$list&&preg_match('#^'.$form.'s?(/|$)#',$uri))return TRUE;
 if($path==='admin/dues'&&preg_match('#^admin/(dues?|due_payment_record|billing_campaign)(/|$)#',$uri))return TRUE;
 if(strpos($path,'admin/posts/')===0&&strpos($uri,'admin/post/'.substr($path,12))===0)return TRUE;
 return (bool)preg_match('#^'.preg_quote($path,'#').'(/|$)#',$uri);
}
